SET NOCOUNT ON; SET XACT_ABORT ON;
IF DB_NAME() <> N'TTSmart_Operational_V1_Test' OR NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=8) THROW 58900,N'Thiếu tiền điều kiện.',1;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=9 AND ScriptChecksum='$(ScriptChecksum)') RETURN;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=9) THROW 58901,N'Checksum không khớp.',1;
BEGIN TRANSACTION;
DECLARE @OperationalMigrationLockResult int;
EXEC @OperationalMigrationLockResult=sys.sp_getapplock @Resource=N'TTSmart.Operational.V1.Baseline',@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=60000;
IF @OperationalMigrationLockResult<0 THROW 58990,N'Không lấy được application lock Operational v1.',1;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=9 AND ScriptChecksum='$(ScriptChecksum)') BEGIN COMMIT; RETURN; END;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=9) THROW 58901,N'Checksum không khớp.',1;
CREATE TABLE dbo.VoiceSettings (VoiceSettingId uniqueidentifier NOT NULL CONSTRAINT PK_VoiceSettings PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, SourcePath nvarchar(1000) NOT NULL, SourceCreatedAtUtc datetime2(7) NULL, SourceUpdatedAtUtc datetime2(7) NULL, MigratedAtUtc datetime2(7) NULL, CreatedAtUtc datetime2(7) NULL, UpdatedAtUtc datetime2(7) NULL, Version int NOT NULL CONSTRAINT DF_VoiceSettings_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT UQ_VoiceSettings_PublicId UNIQUE(PublicId), CONSTRAINT CK_VoiceSettings_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_VoiceSettings_Version CHECK(Version>=0));
CREATE TABLE dbo.VoiceWords (VoiceWordId uniqueidentifier NOT NULL CONSTRAINT PK_VoiceWords PRIMARY KEY, VoiceSettingId uniqueidentifier NOT NULL, SourcePath nvarchar(700) NOT NULL, SortOrder int NOT NULL, WordType nvarchar(30) NOT NULL CONSTRAINT DF_VoiceWords_Type DEFAULT N'Word', Value nvarchar(300) NOT NULL, Keyword nvarchar(300) NULL, Label nvarchar(300) NULL, Pattern nvarchar(1000) NULL, LegacyDuplicateIndex int NOT NULL CONSTRAINT DF_VoiceWords_Duplicate DEFAULT 0, CONSTRAINT FK_VoiceWords_Setting FOREIGN KEY(VoiceSettingId) REFERENCES dbo.VoiceSettings(VoiceSettingId), CONSTRAINT UQ_VoiceWords_LegacyPath UNIQUE(VoiceSettingId,SourcePath,LegacyDuplicateIndex));
CREATE TABLE dbo.VoiceAliases (VoiceAliasId uniqueidentifier NOT NULL CONSTRAINT PK_VoiceAliases PRIMARY KEY, VoiceSettingId uniqueidentifier NOT NULL, SourcePath nvarchar(700) NOT NULL, SortOrder int NOT NULL, AliasType nvarchar(30) NOT NULL CONSTRAINT DF_VoiceAliases_Type DEFAULT N'Alias', Value nvarchar(300) NOT NULL, Keyword nvarchar(300) NULL, Label nvarchar(300) NULL, Pattern nvarchar(1000) NULL, LegacyDuplicateIndex int NOT NULL CONSTRAINT DF_VoiceAliases_Duplicate DEFAULT 0, CONSTRAINT FK_VoiceAliases_Setting FOREIGN KEY(VoiceSettingId) REFERENCES dbo.VoiceSettings(VoiceSettingId), CONSTRAINT UQ_VoiceAliases_LegacyPath UNIQUE(VoiceSettingId,SourcePath,LegacyDuplicateIndex));
CREATE TABLE dbo.VoiceAliasValues (VoiceAliasValueId uniqueidentifier NOT NULL CONSTRAINT PK_VoiceAliasValues PRIMARY KEY, VoiceAliasId uniqueidentifier NOT NULL, SourcePath nvarchar(700) NOT NULL, SortOrder int NOT NULL, Value nvarchar(500) NOT NULL, LegacyDuplicateIndex int NOT NULL CONSTRAINT DF_VoiceAliasValues_Duplicate DEFAULT 0, CONSTRAINT FK_VoiceAliasValues_Alias FOREIGN KEY(VoiceAliasId) REFERENCES dbo.VoiceAliases(VoiceAliasId), CONSTRAINT UQ_VoiceAliasValues_LegacyPath UNIQUE(VoiceAliasId,SourcePath,LegacyDuplicateIndex));
CREATE TABLE dbo.VoiceCodeMaps (VoiceCodeMapId uniqueidentifier NOT NULL CONSTRAINT PK_VoiceCodeMaps PRIMARY KEY, VoiceSettingId uniqueidentifier NOT NULL, SourcePath nvarchar(700) NOT NULL, SortOrder int NOT NULL, Code nvarchar(300) NOT NULL, Keyword nvarchar(300) NULL, Brand nvarchar(300) NULL, ProductType nvarchar(300) NULL, Compact nvarchar(500) NULL, LegacyDuplicateIndex int NOT NULL CONSTRAINT DF_VoiceCodeMaps_Duplicate DEFAULT 0, CONSTRAINT FK_VoiceCodeMaps_Setting FOREIGN KEY(VoiceSettingId) REFERENCES dbo.VoiceSettings(VoiceSettingId), CONSTRAINT UQ_VoiceCodeMaps_LegacyPath UNIQUE(VoiceSettingId,SourcePath,LegacyDuplicateIndex));
CREATE TABLE dbo.VoiceCodeMapPatterns (VoiceCodeMapPatternId uniqueidentifier NOT NULL CONSTRAINT PK_VoiceCodeMapPatterns PRIMARY KEY, VoiceCodeMapId uniqueidentifier NOT NULL, SourcePath nvarchar(700) NOT NULL, SortOrder int NOT NULL, Pattern nvarchar(1000) NOT NULL, LegacyDuplicateIndex int NOT NULL CONSTRAINT DF_VoiceCodeMapPatterns_Duplicate DEFAULT 0, CONSTRAINT FK_VoiceCodeMapPatterns_Map FOREIGN KEY(VoiceCodeMapId) REFERENCES dbo.VoiceCodeMaps(VoiceCodeMapId), CONSTRAINT UQ_VoiceCodeMapPatterns_LegacyPath UNIQUE(VoiceCodeMapId,SourcePath,LegacyDuplicateIndex));
CREATE TABLE dbo.Integrations (IntegrationId uniqueidentifier NOT NULL CONSTRAINT PK_Integrations PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, ProviderCode nvarchar(50) NOT NULL, SecretReferenceCode nvarchar(200) NULL, IsEnabled bit NOT NULL CONSTRAINT DF_Integrations_Enabled DEFAULT 0, Version int NOT NULL CONSTRAINT DF_Integrations_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT UQ_Integrations_PublicId UNIQUE(PublicId), CONSTRAINT UQ_Integrations_Provider UNIQUE(ProviderCode), CONSTRAINT CK_Integrations_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_Integrations_Version CHECK(Version>=0));
CREATE TABLE dbo.NotificationRecipients (NotificationRecipientId uniqueidentifier NOT NULL CONSTRAINT PK_NotificationRecipients PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, IntegrationId uniqueidentifier NOT NULL, RecipientLabel nvarchar(300) NULL, RecipientType nvarchar(50) NOT NULL CONSTRAINT DF_NotificationRecipients_Type DEFAULT N'External', RecipientReferenceCode nvarchar(200) NOT NULL, SortOrder int NOT NULL CONSTRAINT DF_NotificationRecipients_Sort DEFAULT 0, IsEnabled bit NOT NULL CONSTRAINT DF_NotificationRecipients_Enabled DEFAULT 1, Version int NOT NULL CONSTRAINT DF_NotificationRecipients_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT FK_NotificationRecipients_Integration FOREIGN KEY(IntegrationId) REFERENCES dbo.Integrations(IntegrationId), CONSTRAINT UQ_NotificationRecipients_PublicId UNIQUE(PublicId), CONSTRAINT CK_NotificationRecipients_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_NotificationRecipients_Version CHECK(Version>=0));
CREATE TABLE dbo.NotificationSubscriptions (NotificationSubscriptionId uniqueidentifier NOT NULL CONSTRAINT PK_NotificationSubscriptions PRIMARY KEY, NotificationRecipientId uniqueidentifier NOT NULL, EventCode nvarchar(100) NOT NULL, CONSTRAINT FK_NotificationSubscriptions_Recipient FOREIGN KEY(NotificationRecipientId) REFERENCES dbo.NotificationRecipients(NotificationRecipientId), CONSTRAINT UQ_NotificationSubscriptions_Event UNIQUE(NotificationRecipientId,EventCode));
INSERT dbo.SchemaVersions SELECT NEWID(),N'Operational',9,N'009_CreateVoiceAndIntegrationTables.sql','$(ScriptChecksum)',SYSUTCDATETIME(),ORIGINAL_LOGIN(); COMMIT;
